// Tenant guard. "Rooms tool" is SHARED by every client, so it must be told whose data this is: the account
// id from the conversation, or the calling workflow (the database maps it to its client). It never falls
// back to a default: that is how a booking would land in the wrong hotel.
const inp = $input.first().json || {};
let d = inp;
if (typeof inp.query === 'string') { try { d = JSON.parse(inp.query); } catch (e) { d = inp; } }
else if (inp.query && typeof inp.query === 'object') { d = inp.query; }
const acct = String(d.accountId ?? '').trim(), wf = String(d.workflowId ?? '').trim();
if (!/^\d+$/.test(acct) && !wf) throw new Error('Rooms tool was called without accountId or workflowId - refusing to guess whose data to use.');
return [{ json: Object.assign({}, d, { accountId: acct, workflowId: wf }) }];

const rows = $input.all().map((i) => i.json || {});
if (rows.find((r) => r.error)) return [{ json: { message: 'The room list is unavailable right now. Do not guess rooms; offer to connect the guest with a person.' } }];
const rooms = rows.map((r) => r.room).filter(Boolean);
return rooms.length ? rooms.map((r) => ({ json: r })) : [{ json: { message: 'No rooms are listed for this hotel yet. Do not invent rooms; offer to connect the guest with a person.' } }];
